content.css:
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  display: block;
  background: #ffffff;
}
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* FTE Decision Board specific */
.fte-board {
  scrollbar-width: thin;
  scrollbar-color: #cbd5e1 transparent;
}
.fte-board::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.fte-board::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 3px;
}
.fte-kpi-bar {
  animation: fte-fadein 0.4s ease;
}
@keyframes fte-fadein {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
/* ========================================================================== */
/* Insight Panel                                                              */
/* ========================================================================== */
.fte-board-layout {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: row;
  position: relative;
  overflow: hidden;
}
.fte-board-layout--narrow .fte-insight-panel,
.fte-board-layout--narrow .fte-insight-strip {
  position: absolute;
  right: 0;
  top: 0;
  z-index: 30;
  box-shadow: -4px 0 10px rgba(15, 23, 42, 0.06);
}
.fte-insight-panel {
  width: 300px;
  flex: 0 0 300px;
  background: #f9fafb;
  border-left: 1px solid #e5e7eb;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 30px 10px 28px 10px;
  box-sizing: border-box;
  font-family: "Segoe UI", Tahoma, sans-serif;
  position: relative;
  animation: fte-fadein 0.25s ease;
  scrollbar-width: thin;
  scrollbar-color: #cbd5e1 transparent;
}
.fte-insight-panel::-webkit-scrollbar {
  width: 6px;
}
.fte-insight-panel::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 3px;
}
.fte-insight-panel__collapse {
  position: absolute;
  top: 6px;
  right: 6px;
  font-size: 12px;
  font-weight: 700;
  color: #6b7280;
  cursor: pointer;
  user-select: none;
  padding: 2px 7px;
  border-radius: 4px;
  z-index: 2;
  line-height: 1;
  transition: background-color 0.15s, color 0.15s;
}
.fte-insight-panel__collapse:hover {
  background: rgba(232, 97, 42, 0.12);
  color: #E8612A;
}
.fte-insight-strip {
  width: 22px;
  flex: 0 0 22px;
  background: transparent;
  border-left: 1px solid #e5e7eb;
  cursor: pointer;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 10px;
  user-select: none;
  transition: background-color 0.15s;
}
.fte-insight-strip:hover {
  background: rgba(232, 97, 42, 0.08);
}
.fte-insight-strip .fte-insight-strip__chev {
  font-size: 12px;
  font-weight: 700;
  color: #6b7280;
}
.fte-insight-strip:hover .fte-insight-strip__chev {
  color: #E8612A;
}
/* ── Panel sections ── */
.fte-ip-section {
  margin-bottom: 8px;
}
.fte-ip-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #f8fafc, #f1f5f9);
  border-radius: 10px;
  border-left: 4px solid #059669;
}
.fte-ip-eff-badge {
  min-width: 42px;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  flex-shrink: 0;
}
.fte-ip-eff-badge span {
  line-height: 1;
}
.fte-ip-eff-text {
  min-width: 0;
  flex: 1;
}
.fte-ip-eff-title {
  font-size: 12px;
  font-weight: 700;
  color: #111827;
  line-height: 1.2;
}
.fte-ip-eff-sub {
  font-size: 10px;
  color: #6b7280;
  margin-top: 2px;
  line-height: 1.3;
}
.fte-ip-card {
  padding: 8px 10px;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
}
.fte-ip-card-title {
  font-size: 11px;
  font-weight: 700;
  color: #111827;
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 5px;
}
.fte-ip-icon {
  font-size: 13px;
}
.fte-ip-card-body {
  font-size: 10.5px;
  color: #374151;
  line-height: 1.55;
}
.fte-ip-card-body b {
  font-weight: 600;
  color: #111827;
}
.fte-ip-alert {
  padding: 8px 10px;
  border-radius: 8px;
}
.fte-ip-alert--red {
  background: #FEF2F2;
  border: 1px solid #FECACA;
}
.fte-ip-alert--red .fte-ip-alert-title {
  color: #991B1B;
}
.fte-ip-alert--red .fte-ip-alert-body {
  color: #7F1D1D;
}
.fte-ip-alert--red .fte-ip-alert-body b {
  color: #7F1D1D;
}
.fte-ip-alert--amber {
  background: #FFFBEB;
  border: 1px solid #FDE68A;
}
.fte-ip-alert--amber .fte-ip-alert-title {
  color: #92400E;
}
.fte-ip-alert--amber .fte-ip-alert-body {
  color: #78350F;
}
.fte-ip-alert--amber .fte-ip-alert-body b {
  color: #78350F;
}
.fte-ip-alert--indigo {
  background: #EEF2FF;
  border: 1px solid #C7D2FE;
}
.fte-ip-alert--indigo .fte-ip-alert-title {
  color: #3730A3;
}
.fte-ip-alert--indigo .fte-ip-alert-body {
  color: #312E81;
}
.fte-ip-alert--indigo .fte-ip-alert-body b {
  color: #312E81;
}
.fte-ip-alert-title {
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 3px;
  display: flex;
  align-items: center;
  gap: 5px;
}
.fte-ip-alert-body {
  font-size: 10.5px;
  line-height: 1.55;
}
.fte-ip-severe {
  color: #dc2626;
  font-weight: 700;
}
.fte-ip-actions {
  line-height: 1.6;
}
.fte-ip-action {
  display: flex;
  gap: 6px;
  align-items: flex-start;
  margin-bottom: 4px;
}
.fte-ip-action-tag {
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  white-space: nowrap;
  margin-top: 1px;
  flex-shrink: 0;
  letter-spacing: 0.3px;
}
.fte-ip-action-body {
  font-size: 10.5px;
  color: #374151;
  line-height: 1.55;
}
.fte-ip-action-body b {
  color: #111827;
  font-weight: 600;
}
.fte-ip-action-body i {
  color: #6b7280;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
